wrap.append(label,input,results,selected);heading.append(wrap);
let timer,controller,activeSymbol='';
function pick(x){activeSymbol=x.symbol;input.value=x.symbol+' — '+x.name;selected.textContent='Selected: '+x.symbol+' · NSE. Run Stock Scan or open Chart Lab.';results.style.display='none';const chart=root.querySelector('#chart-symbol');if(chart)chart.value=x.symbol;const universe=root.querySelector('#stock-universe');if(universe){let opt=[...universe.options].find(o=>o.value==='selected-symbol');if(!opt){opt=document.createElement('option');opt.value='selected-symbol';opt.textContent='Selected Symbol';universe.append(opt)}universe.value='selected-symbol'}root.dispatchEvent(new CustomEvent('sp-symbol-selected',{detail:x}));}
input.addEventListener('input',()=>{clearTimeout(timer);activeSymbol='';const q=input.value.trim();if(q.length<1){results.style.display='none';return}timer=setTimeout(async()=>{if(controller)controller.abort();controller=new AbortController();try{const r=await fetch(base+'/api/stock-search?q='+encodeURIComponent(q),{signal:controller.signal}),j=await r.json();if(!j.success)throw Error(j.error||'Search unavailable');results.replaceChildren();for(const x of j.results||[]){const b=document.createElement('button');b.type='button';b.setAttribute('role','option');b.textContent=x.symbol+' — '+x.name;b.style.cssText='display:block;width:100%;text-align:left;padding:11px 13px;border:0;border-bottom:1px solid #eef2f9;background:#fff;color:#243344;cursor:pointer';b.addEventListener('click',()=>pick(x));results.append(b)}if(!results.children.length){const p=document.createElement('p');p.textContent='No matching symbols. Try exact NSE ticker.';p.style.padding='12px';results.append(p)}results.style.display='block'}catch(e){if(e.name!=='AbortError')selected.textContent='Search temporarily unavailable: '+e.message}},260)});
